// "Conferir no Bipe" phase 1 (bipe ADR 0091, payments.md item 5a): read the Pix code and the
// Pix keys in text that a user shared from another app. Runs on the device only.
// Reference implementation: every platform must match test-vectors/pix-check.json.

import { scamWarningKind } from "./registries.mjs";

const PIX_GUI = "br.gov.bcb.pix";
const UUID = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

// Warning kinds the check screen does not repeat: the screen itself is the Pix explanation.
export const PIX_CHECK_SKIPPED_WARNINGS = ["pixCode", "pixKey"];

/** CRC-16/CCITT-FALSE (poly 0x1021, init 0xFFFF) over the UTF-8 bytes, as 4 uppercase hex digits. TextEncoder, not Buffer: bipe-web runs this in the browser. */
export function crc16(text) {
  let crc = 0xffff;
  for (const byte of new TextEncoder().encode(text)) {
    crc ^= byte << 8;
    for (let i = 0; i < 8; i++) crc = crc & 0x8000 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
  }
  return crc.toString(16).toUpperCase().padStart(4, "0");
}

/** The kind of a Pix key as DICT stores it: cpf, cnpj, phone (+55...), email, random, or unknown. */
export function pixKeyType(key) {
  if (key.includes("@")) return "email";
  if (/^\+[0-9]{12,13}$/.test(key)) return "phone";
  if (UUID.test(key)) return "random";
  if (/^[0-9]{11}$/.test(key)) return "cpf";
  if (/^[0-9A-Z]{12}[0-9]{2}$/.test(key)) return "cnpj";
  return "unknown";
}

// EMV TLV: two-digit ID, two-digit length, value. Lengths count code points.
// Returns [{ id, value, start, end }] (code point offsets), or null when the shape is wrong.
function readTLV(points, from, until) {
  const fields = [];
  let i = from;
  while (i < until) {
    if (i + 4 > until) return null;
    const head = points.slice(i, i + 4).join("");
    if (!/^[0-9]{4}$/.test(head)) return null;
    const len = Number(head.slice(2));
    if (i + 4 + len > until) return null;
    fields.push({ id: head.slice(0, 2), value: points.slice(i + 4, i + 4 + len).join(""), start: i, end: i + 4 + len });
    i += 4 + len;
    if (head.slice(0, 2) === "63") break;
  }
  return fields;
}

// Lowercases A-Z only, so every platform folds the same characters.
const asciiLower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase());

// The first BR Code in the text: { start, end, code } in code points, with the parsed result.
// It starts at the first "000201" that has br.gov.bcb.pix after it.
function findBrCode(points) {
  for (let start = 0; start + 6 <= points.length; start++) {
    if (points.slice(start, start + 6).join("") !== "000201") continue;
    if (!asciiLower(points.slice(start).join("")).includes(PIX_GUI)) return null;
    const fields = readTLV(points, start, points.length);
    if (!fields) return { start, end: points.length, code: { status: "malformed" } };
    return { start, end: fields[fields.length - 1].end, code: parseFields(points, start, fields) };
  }
  return null;
}

function parseFields(points, start, fields) {
  const malformed = { status: "malformed" };
  const crcField = fields[fields.length - 1];
  if (fields[0].id !== "00" || fields[0].value !== "01") return malformed;
  if (crcField.id !== "63" || crcField.value.length !== 4) return malformed;
  const byId = new Map(fields.map((f) => [f.id, f.value]));

  let account = null;
  for (const f of fields) {
    const n = Number(f.id);
    if (n < 26 || n > 51) continue;
    const sub = readTLV(Array.from(f.value), 0, Array.from(f.value).length);
    if (!sub) continue;
    const subs = new Map(sub.map((s) => [s.id, s.value]));
    if (asciiLower(subs.get("00") ?? "") === PIX_GUI) { account = subs; break; }
  }
  if (!account) return malformed;
  const key = account.get("01") ?? null;
  const url = account.get("25") ?? null;
  if (!key && !url) return malformed;

  let txid = null;
  const extra = byId.get("62");
  if (extra) {
    const sub = readTLV(Array.from(extra), 0, Array.from(extra).length);
    if (!sub) return malformed;
    const t = sub.find((s) => s.id === "05")?.value ?? null;
    txid = t && t !== "***" ? t : null;
  }

  const signed = points.slice(start, crcField.start + 4).join("");
  return {
    status: crc16(signed) === crcField.value.toUpperCase() ? "valid" : "badCrc",
    dynamic: url !== null,
    singleUse: byId.get("01") === "12",
    key: key ? key.trim() : null,
    keyType: key ? pixKeyType(key.trim()) : null,
    url,
    name: byId.get("59") ?? null,
    city: byId.get("60") ?? null,
    amount: byId.get("54") ?? null,
    txid,
    info: account.get("02") ?? null,
  };
}

/**
 * Key types (pixKeyType): email has "@", phone is "+" and 12 or 13 digits, random is a UUID, cpf is 11 digits,
 * cnpj is 12 of [0-9A-Z] then 2 digits (format only, no check digits), else unknown.
 * The phase 1 check of shared text.
 * code: the first BR Code (status valid, badCrc or malformed, plus its fields when not malformed), or null.
 * keys: Pix keys outside the code, in text order. One entry per span; types lists every pattern that matched it.
 * warning: the rule 9 warning kind of the text without the code, skipping PIX_CHECK_SKIPPED_WARNINGS, or null.
 */
export function pixCheck(text, reg) {
  const points = Array.from(text);
  const found = findBrCode(points);
  const rest = found ? [...points.slice(0, found.start), " ", ...points.slice(found.end)].join("") : text;

  const spans = new Map();
  for (const p of reg.scam.pixKeyPatterns) {
    for (const m of rest.matchAll(new RegExp(p.regex, "g"))) {
      const k = `${m.index}:${m[0].length}`;
      if (!spans.has(k)) spans.set(k, { index: m.index, value: m[0], types: [] });
      spans.get(k).types.push(p.id);
    }
  }
  const keys = [...spans.values()].sort((a, b) => a.index - b.index || b.value.length - a.value.length).map(({ value, types }) => ({ value, types }));

  return {
    code: found ? found.code : null,
    keys,
    // The code is shown field by field, so a payload URL inside it is not a link in the message.
    warning: scamWarningKind(rest, reg, PIX_CHECK_SKIPPED_WARNINGS),
  };
}

/** Builds a static BR Code with a correct CRC. Test vectors only. */
export function buildBrCode({ key, info, name, city, amount, txid = "***", url, singleUse = false }) {
  const f = (id, v) => `${id}${String(Array.from(v).length).padStart(2, "0")}${v}`;
  const account = f("00", PIX_GUI) + (key ? f("01", key) : "") + (info ? f("02", info) : "") + (url ? f("25", url) : "");
  const body = f("00", "01") + (singleUse ? f("01", "12") : "") + f("26", account) + f("52", "0000") + f("53", "986")
    + (amount ? f("54", amount) : "") + f("58", "BR") + f("59", name) + f("60", city) + f("62", f("05", txid)) + "6304";
  return body + crc16(body);
}

// --- Pix request marks (ADR 0046, bipe-chat/bipe#130; registries/pix-marks.json) -------------------

const MARK_FROM = { sent: ["issued", "sent", "not_received"], received: ["issued", "sent", "not_received"], not_received: ["sent", "received"] };

/** The BR Code txid of a request card: the request ID with letters and digits only, at most txidMaxLength. */
export function pixTxid(requestId, marks) {
  return String(requestId ?? "").replace(/[^A-Za-z0-9]/g, "").slice(0, marks.txidMaxLength);
}

/** true when the E2E ID has the format of a Pix end-to-end ID. The app cannot check that the payment exists. */
export function pixE2eIdValid(id, marks) {
  return typeof id === "string" && new RegExp(marks.e2eIdPattern).test(id);
}

/**
 * The lines of a request card from its mark events.
 * card: { event_id, requester, payers: [user IDs] }. events: [{ event_id, sender, ts, content }].
 * Returns { lines: [{ payer, state, e2e_id, paid, history: [{ event_id, mark }] }] in payer order, rejected: [event IDs] }.
 */
export function pixMarkLines(card, events, marks) {
  const lines = new Map((card.payers ?? []).map((payer) => [payer, { payer, state: "issued", e2e_id: null, paid: false, history: [] }]));
  const rejected = [];
  const ordered = [...(events ?? [])].sort((a, b) => (a.ts - b.ts) || (a.event_id < b.event_id ? -1 : a.event_id > b.event_id ? 1 : 0));
  for (const event of ordered) {
    const line = pixMarkLine(card, event, lines, marks);
    if (!line) {
      rejected.push(event.event_id);
      continue;
    }
    const mark = event.content.mark;
    line.state = mark;
    if (mark === "sent") line.e2e_id = event.content.e2e_id ?? null;
    line.paid = mark === "received";
    line.history.push({ event_id: event.event_id, mark });
  }
  return { lines: [...lines.values()], rejected };
}

// The line an event may change, or null when the event breaks a rule.
function pixMarkLine(card, event, lines, marks) {
  const content = event?.content;
  if (!content || typeof content !== "object" || Array.isArray(content)) return null;
  const rel = content["m.relates_to"];
  if (!rel || rel.rel_type !== marks.relType || rel.event_id !== card.event_id) return null;
  const mark = content.mark;
  if (!marks.marks.includes(mark)) return null;
  if ("payer" in content && typeof content.payer !== "string") return null;
  if ("e2e_id" in content && (mark !== "sent" || !pixE2eIdValid(content.e2e_id, marks))) return null;
  let payer;
  if (mark === "sent") {
    if (content.payer !== undefined && content.payer !== event.sender) return null;
    payer = event.sender;
  } else {
    if (event.sender !== card.requester) return null;
    payer = content.payer ?? (lines.size === 1 ? [...lines.keys()][0] : undefined);
  }
  const line = lines.get(payer);
  if (!line || !MARK_FROM[mark].includes(line.state)) return null;
  return line;
}
